// Base64-embedded copies of the featured-cube textures.
// WebGL texture uploads are blocked by canvas-tainting rules when this
// page is opened directly as a file:// URL (same reason the 3D logo GLB
// is embedded below) — embedding avoids that entirely, working the same
// whether the page is opened as a file or served over http(s).
//
// `collage` is the original: it skins the cube's top and bottom caps and
// one side. side1..side3 are the other three sides. Regenerate with the
// snippet in box/ if the source collages change.
window.NAV_PHOTO_B64 = {
  collage: "data:image/jpeg;base64,",
  side1: "data:image/jpeg;base64,",
  side2: "data:image/jpeg;base64,",
  side3: "data:image/jpeg;base64,"
};
